				requested, worker := requireA2PortfolioOperatingCreation(t, rt, trigger, wirePayload, "operating_instance_id")
				if workers[worker.Entity.EntityID] {
					t.Fatalf("independent trigger borrowed an earlier worker: %+v", worker)
				}
